-- ERPNext business-suite breadth: bank statement reconciliation, payroll,
-- recurring subscriptions, provider-safe e-invoice queueing and CRM/portal metadata.

CREATE TABLE IF NOT EXISTS bank_reconciliation_entries (
  tenant_id TEXT NOT NULL, voucher_type TEXT NOT NULL, voucher_no TEXT NOT NULL, voucher_revision INTEGER NOT NULL,
  line_key TEXT NOT NULL, bank_account TEXT NOT NULL, bank_transaction TEXT NOT NULL,
  against_voucher_type TEXT NOT NULL, against_voucher_no TEXT NOT NULL, amount_minor INTEGER NOT NULL,
  currency TEXT NOT NULL, currency_scale INTEGER NOT NULL CHECK(currency_scale BETWEEN 0 AND 6), posting_at TEXT NOT NULL,
  PRIMARY KEY(tenant_id,voucher_type,voucher_no,voucher_revision,line_key)
);
CREATE INDEX IF NOT EXISTS idx_bank_reconciliation_transaction ON bank_reconciliation_entries(tenant_id,bank_transaction,posting_at);

CREATE TRIGGER IF NOT EXISTS bank_reconciliation_amount_guard
BEFORE INSERT ON bank_reconciliation_entries
BEGIN
  SELECT CASE
    WHEN NOT EXISTS(SELECT 1 FROM documents d WHERE d.tenant_id=NEW.tenant_id AND d.doctype='Bank Transaction' AND d.name=NEW.bank_transaction AND d.docstatus=1)
      THEN RAISE(ABORT,'BANK_TRANSACTION_NOT_SUBMITTED')
    WHEN COALESCE((SELECT SUM(amount_minor) FROM bank_reconciliation_entries e WHERE e.tenant_id=NEW.tenant_id AND e.bank_transaction=NEW.bank_transaction),0)+NEW.amount_minor < 0
      THEN RAISE(ABORT,'BANK_RECONCILIATION_NEGATIVE')
    WHEN COALESCE((SELECT SUM(amount_minor) FROM bank_reconciliation_entries e WHERE e.tenant_id=NEW.tenant_id AND e.bank_transaction=NEW.bank_transaction),0)+NEW.amount_minor
      > COALESCE((SELECT ABS(CAST(json_extract(d.payload_json,'$.amount_minor') AS INTEGER)) FROM documents d WHERE d.tenant_id=NEW.tenant_id AND d.doctype='Bank Transaction' AND d.name=NEW.bank_transaction AND d.docstatus=1),-1)
      THEN RAISE(ABORT,'BANK_RECONCILIATION_OVER_ALLOCATED')
  END;
END;

CREATE TRIGGER IF NOT EXISTS payroll_salary_slip_unique_guard
BEFORE INSERT ON document_children
WHEN NEW.fieldname='salary_slips'
 AND EXISTS(SELECT 1 FROM documents p WHERE p.tenant_id=NEW.tenant_id AND p.doc_key=NEW.parent_key AND p.doctype='Payroll Entry' AND p.docstatus=1)
 AND EXISTS(SELECT 1 FROM document_children c JOIN documents p ON p.tenant_id=c.tenant_id AND p.doc_key=c.parent_key
   WHERE c.tenant_id=NEW.tenant_id AND c.fieldname='salary_slips' AND p.doctype='Payroll Entry' AND p.docstatus=1
     AND c.parent_key<>NEW.parent_key AND json_extract(c.payload_json,'$.salary_slip')=json_extract(NEW.payload_json,'$.salary_slip'))
BEGIN SELECT RAISE(ABORT,'SALARY_SLIP_ALREADY_IN_PAYROLL'); END;

CREATE TRIGGER IF NOT EXISTS e_invoice_single_active_insert
BEFORE INSERT ON documents
WHEN NEW.doctype='E-Invoice Submission' AND NEW.docstatus=1
 AND EXISTS(SELECT 1 FROM documents e WHERE e.tenant_id=NEW.tenant_id AND e.doctype='E-Invoice Submission' AND e.docstatus=1
   AND json_extract(e.payload_json,'$.source_doctype')=json_extract(NEW.payload_json,'$.source_doctype')
   AND json_extract(e.payload_json,'$.source_name')=json_extract(NEW.payload_json,'$.source_name'))
BEGIN SELECT RAISE(ABORT,'E_INVOICE_ALREADY_SUBMITTED'); END;
CREATE TRIGGER IF NOT EXISTS e_invoice_single_active_update
BEFORE UPDATE OF docstatus,payload_json ON documents
WHEN NEW.doctype='E-Invoice Submission' AND NEW.docstatus=1
 AND EXISTS(SELECT 1 FROM documents e WHERE e.tenant_id=NEW.tenant_id AND e.doctype='E-Invoice Submission' AND e.docstatus=1 AND e.doc_key<>NEW.doc_key
   AND json_extract(e.payload_json,'$.source_doctype')=json_extract(NEW.payload_json,'$.source_doctype')
   AND json_extract(e.payload_json,'$.source_name')=json_extract(NEW.payload_json,'$.source_name'))
BEGIN SELECT RAISE(ABORT,'E_INVOICE_ALREADY_SUBMITTED'); END;

CREATE VIEW IF NOT EXISTS bank_reconciliation_summary AS
SELECT e.tenant_id,e.bank_account,e.bank_transaction,e.currency,
       SUM(e.amount_minor)/100.0 AS reconciled_amount,
       MAX(e.posting_at) AS last_reconciled_at,COUNT(*) AS match_count
FROM bank_reconciliation_entries e GROUP BY e.tenant_id,e.bank_account,e.bank_transaction,e.currency;

CREATE VIEW IF NOT EXISTS payroll_register AS
SELECT tenant_id,name AS salary_slip,json_extract(payload_json,'$.employee') AS employee,json_extract(payload_json,'$.company') AS company,
       json_extract(payload_json,'$.start_date') AS start_date,json_extract(payload_json,'$.end_date') AS end_date,
       CAST(json_extract(payload_json,'$.gross_pay_minor') AS INTEGER)/100.0 AS gross_pay,
       CAST(json_extract(payload_json,'$.total_deduction_minor') AS INTEGER)/100.0 AS total_deduction,
       CAST(json_extract(payload_json,'$.net_pay_minor') AS INTEGER)/100.0 AS net_pay,status
FROM documents WHERE doctype='Salary Slip' AND docstatus<>2;

CREATE VIEW IF NOT EXISTS subscription_schedule AS
SELECT tenant_id,name AS subscription,json_extract(payload_json,'$.customer') AS customer,json_extract(payload_json,'$.company') AS company,
       json_extract(payload_json,'$.subscription_plan') AS subscription_plan,json_extract(payload_json,'$.next_invoice_date') AS next_invoice_date,
       CAST(json_extract(payload_json,'$.amount_minor') AS INTEGER)/100.0 AS amount,json_extract(payload_json,'$.currency') AS currency,status
FROM documents WHERE doctype='Subscription' AND docstatus=1;

CREATE VIEW IF NOT EXISTS e_invoice_submission_log AS
SELECT tenant_id,name AS submission,json_extract(payload_json,'$.source_doctype') AS source_doctype,json_extract(payload_json,'$.source_name') AS source_name,
       json_extract(payload_json,'$.provider') AS provider,json_extract(payload_json,'$.submission_status') AS submission_status,modified_at
FROM documents WHERE doctype='E-Invoice Submission';

